export function evaluate({ inputs, time }) {
 const g = 9.8, u = inputs.launchSpeed;
 const T = 2 * u / g;
 const t = Math.max(0, Math.min(time, T));
 const tt = u / g;
 const h = u * t - g * t * t / 2;
 const v = u - g * t;
 const apexH = u * u / (2 * g);
 const top = Math.abs(t - tt) < 0.005;
 const vv = top ? 0 : v;
 const base = 370, sc = 55;
 const y = base - h * sc;
 const x = 200;
 const state = top ? 'Still for an instant' : (v > 0 ? 'Moving up' : 'Moving down');
 const o = [];
 o.push(...sdk.panel({ x: 20, y: 40, w: 600, h: 360, title: 'Tossed ball', state: state, id: 'lane.toss' }));
 o.push(sdk.line('guide.l', 90, base + 14, 310, base + 14, { role: 'neutral' }));
 o.push(sdk.text('guide.t', 330, base + 18, 'Launch height', { role: 'neutral' }));
 o.push(sdk.circle('ball.toss', x, y, 28, { role: 'observed' }));
 o.push(...sdk.vector('vec.v', { x: x + 40, y: y }, { value: vv, direction: 'up' }, { scale: 14, label: 'v', role: 'input' }));
 o.push(...sdk.vector('vec.a', { x: x + 90, y: y }, { value: -g, direction: 'up' }, { scale: 4, label: 'a', role: 'warning' }));
 o.push(...sdk.callout(400, 150, [state, 'Gravity pulls down'], { id: 'callout.toss' }));
 return { frame: { width: 640, height: 420, objects: o, readouts: [{ id: 'motionState', value: state }, { id: 'gravityState', value: 'Gravity pulls down' }] }, quantities: { launchSpeed: u, gravity: g, apexTime: tt, apexHeight: apexH, velocity: vv, height: h } };
}
